109	template <AccPhase Phase = AccPhase::Unspecified, typename TileRes, typename TileLeft, typename TileRight>
110	PTO_INTERNAL void TGEMV_IMPL(TileRes& cMatrix, TileLeft& aMatrix, TileRight& bMatrix)
111	{
112	    CheckStaticMad<TileRes, TileLeft, TileRight>();
113	    uint16_t k = bMatrix.GetValidRow();
114	    uint16_t n = bMatrix.GetValidCol();
115	    bool kDirectionAlign = GetKDirectionAlign(aMatrix, bMatrix);
116	    PTO_ASSERT(k >= 1 && k <= MMAD_MAX_SUPPORT_LENGTH, "ERROR: The range of valid aMatrixCol is [1, 4095].");
117	    PTO_ASSERT(n >= 1 && n <= MMAD_MAX_SUPPORT_LENGTH, "ERROR: The range of valid bMatrixCol is [1, 4095].");
118	
119	    TMatmul<Phase, TileRes, TileLeft, TileRight, false, true, true>(
120	        cMatrix.data(), aMatrix.data(), bMatrix.data(), 1, k, n, kDirectionAlign);
121	}
