69	#define PTO_A6_DISPATCH_MAD(C_PTR, A_PTR, B_PTR, M_VAL, K_VAL, N_VAL)                                           \
70	    do {                                                                                                        \
71	        if constexpr (kIsMmadS8S4<TileRes, TileLeft, TileRight>) {                                              \
72	            mad_s8s4(                                                                                           \
73	                C_PTR, A_PTR, B_PTR, M_VAL, K_VAL, N_VAL, static_cast<uint8_t>(Phase), gemvCtrl, cmatrixSource, \
74	                cmatrixInitVal);                                                                                \
75	        } else if constexpr (kIsMmadBf16S4<TileRes, TileLeft, TileRight>) {                                     \
76	            mad_bf16s4(                                                                                         \
77	                C_PTR, A_PTR, B_PTR, M_VAL, K_VAL, N_VAL, static_cast<uint8_t>(Phase), gemvCtrl, cmatrixSource, \
78	                cmatrixInitVal);                                                                                \
79	        } else if constexpr (kIsMmadF16S4<TileRes, TileLeft, TileRight>) {                                      \
80	            mad_f16s4(                                                                                          \
81	                C_PTR, A_PTR, B_PTR, M_VAL, K_VAL, N_VAL, static_cast<uint8_t>(Phase), gemvCtrl, cmatrixSource, \
82	                cmatrixInitVal);                                                                                \
83	        } else {                                                                                                \
84	            mad(C_PTR, A_PTR, B_PTR, M_VAL, K_VAL, N_VAL, static_cast<uint8_t>(Phase), gemvCtrl, cmatrixSource, \
85	                cmatrixInitVal);                                                                                \
86	        }                                                                                                       \
87	    } while (false)
