89	template <
90	    AccPhase Phase = AccPhase::Unspecified, typename TileRes, typename TileLeft, typename TileRight, bool cmatrixSource,
91	    bool cmatrixInitVal, bool gemvCtrl>
92	__tf__ AICORE void TMatmul(
93	    typename TileRes::TileDType __out__ cMatrix, typename TileLeft::TileDType __in__ aMatrix,
94	    typename TileRight::TileDType __in__ bMatrix, uint16_t m, uint16_t k, uint16_t n)
95	{
96	    // when gemv = 1 , GEMV mode is disable.
97	    __cc__ typename TileRes::DType* c = (__cc__ typename TileRes::DType*)__cce_get_tile_ptr(cMatrix);
98	    __ca__ typename TileLeft::DType* a = (__ca__ typename TileLeft::DType*)__cce_get_tile_ptr(aMatrix);
99	    __cb__ typename TileRight::DType* b = (__cb__ typename TileRight::DType*)__cce_get_tile_ptr(bMatrix);
100	
101	    PTO_A6_DISPATCH_MAD(c, a, b, m, k, n);
102	}
