203	template <typename TileRes, typename TileLeft, typename TileLeftScale, typename TileRight, typename TileRightScale>
204	PTO_INTERNAL void CheckMadMxValid()
205	{
206	    constexpr const int BASEK = 64;
207	    using AType = typename TileLeft::DType;
208	    using BType = typename TileRight::DType;
209	    using CType = typename TileRes::DType;
210	    constexpr bool isFp4 = isSupportedFp4Combo<AType, BType>;
211	    constexpr bool isFp8 = isSupportedFp8Combo<AType, BType>;
212	    constexpr bool isFp8Fp4 = isSupportedFp8Fp4Combo<AType, BType>;
213	    constexpr bool isFp16Fp4 = isSupportedFp16Fp4Combo<AType, BType>;
214	    constexpr bool isBf16Fp4 = isSupportedBf16Fp4Combo<AType, BType>;
215	    constexpr bool isFp8Hif4 = isSupportedFp8Hif4Combo<AType, BType>;
216	    constexpr bool isFp16Hif4 = isSupportedFp16Hif4Combo<AType, BType>;
217	    constexpr bool isBf16Hif4 = isSupportedBf16Hif4Combo<AType, BType>;
218	    constexpr bool isHif4 = isSupportedHif4Combo<AType, BType>;
219	
220	    static_assert(
221	        (isFp4 || isFp8 || isFp8Fp4 || isFp16Fp4 || isBf16Fp4 || isFp8Hif4 || isFp16Hif4 || isBf16Hif4 || isHif4) &&
222	            std::is_same_v<CType, float>,
223	        "TMatmulMX:No supported data type combination.");
224	    static_assert((TileLeft::Cols % BASEK == 0), "TMatmulMX: aMatrixCol must be a multiple of 64.");
225	    if constexpr (isFp4 || isFp8Fp4 || isHif4) {
226	        static_assert(
227	            (TileLeft::Cols % 2 == 0), "TMatmulMX:For FP4/HiF4 data types, aMatrixCol must be an even number.");
228	    }
229	    static_assert(
230	        ((TileLeft::Loc == TileType::Left) && (!TileLeft::isRowMajor) && (TileLeft::SFractal == SLayout::RowMajor)) &&
231	            ((TileRight::Loc == TileType::Right) && (TileRight::isRowMajor) &&
232	             (TileRight::SFractal == SLayout::ColMajor)) &&
233	            ((TileRes::Loc == TileType::Acc) && (!TileRes::isRowMajor) && (TileRes::SFractal == SLayout::RowMajor)),
234	        "TMatmulMX:Non-conforming matrix fractal");
235	    constexpr size_t accBytes = static_cast<size_t>(TileRes::Rows) * static_cast<size_t>(TileRes::Cols) * sizeof(CType);
236	    static_assert(
237	        accBytes <= PTO_L0C_SIZE_BYTES, "TMatmulMX:accumulator (Rows*Cols*sizeof(out)) exceeds L0C capacity.");
238	}
