250	template <typename TileRes, typename TileLeft, typename TileRight>
251	PTO_INTERNAL void CheckMadValid()
252	{
253	    using AType = typename TileLeft::DType;
254	    using BType = typename TileRight::DType;
255	    using CType = typename TileRes::DType;
256	    static_assert(std::is_same_v<CType, int32_t> || std::is_same_v<CType, float>, "Acc Type support int32_t or float.");
257	    if constexpr (std::is_same_v<CType, int32_t>) {
258	#if defined(PTO_NPU_ARCH_A6)
259	        static_assert(
260	            (std::is_same_v<AType, int8_t> && std::is_same_v<BType, int8_t>) ||
261	                (std::is_same_v<AType, int8_t> && std::is_same_v<BType, int4b_t>),
262	            "For A6 int32 accumulation, supported input pairs are int8xint8 and int8xint4b_t (MMAD.s8s4).");
263	#else
264	        static_assert(
265	            std::is_same_v<AType, int8_t> && std::is_same_v<BType, int8_t>,
266	            "Left Type and Right Type must be int8_t when Acc Type is int32_t.");
267	#endif
268	    } else if constexpr (std::is_same_v<CType, float>) {
269	        static_assert(
270	            (std::is_same_v<AType, half> && std::is_same_v<BType, half>) ||
271	                (std::is_same_v<AType, half> && std::is_same_v<BType, float8_e4m3_t>) ||
272	                (std::is_same_v<AType, half> && std::is_same_v<BType, int4b_t>) ||
273	                (std::is_same_v<AType, bfloat16_t> && std::is_same_v<BType, float8_e4m3_t>) ||
274	                (std::is_same_v<AType, bfloat16_t> && std::is_same_v<BType, int4b_t>) ||
275	                (std::is_same_v<AType, bfloat16_t> && std::is_same_v<BType, int8_t>) ||
276	                (std::is_same_v<AType, half> && std::is_same_v<BType, int8_t>) ||
277	                (std::is_same_v<AType, bfloat16_t> && std::is_same_v<BType, bfloat16_t>) ||
278	                (std::is_same_v<AType, float> && std::is_same_v<BType, float>) ||
279	                (std::is_same_v<AType, float8_e4m3_t> && std::is_same_v<BType, float8_e4m3_t>) ||
280	                (std::is_same_v<AType, float8_e4m3_t> && std::is_same_v<BType, float8_e5m2_t>) ||
281	                (std::is_same_v<AType, float8_e5m2_t> && std::is_same_v<BType, float8_e4m3_t>) ||
282	                (std::is_same_v<AType, float8_e5m2_t> && std::is_same_v<BType, float8_e5m2_t>) ||
283	                (std::is_same_v<AType, hifloat8_t> && std::is_same_v<BType, hifloat8_t>),
284	            "For A6 float accumulation, supported input pairs include halfxhalf (MMAD.f16f32), "
285	            "halfxfloat8_e4m3_t (MMAD.f16e4m3), bfloat16xfloat8_e4m3_t (MMAD.bf16e4m3), "
286	            "halfxint4b_t (MMAD.f16s4), bfloat16xint4b_t (MMAD.bf16s4), "
287	            "halfxint8 (MMAD.f16s8), bfloat16xint8 (MMAD.bf16s8), bfloat16xbfloat16, floatxfloat, "
288	            "selected fp8 pairs, and hifloat8xhifloat8.");
289	    }
290	    static_assert(
291	        ((TileLeft::Loc == TileType::Left) && (!TileLeft::isRowMajor) && (TileLeft::SFractal == SLayout::RowMajor)) &&
292	            ((TileRight::Loc == TileType::Right) && (TileRight::isRowMajor) &&
293	             (TileRight::SFractal == SLayout::ColMajor)) &&
294	            ((TileRes::Loc == TileType::Acc) && (!TileRes::isRowMajor) && (TileRes::SFractal == SLayout::RowMajor)),
295	        "Non-conforming matrix fractal.");
296	}
