298	template <AccPhase Phase = AccPhase::Unspecified, typename TileRes, typename TileLeft, typename TileRight>
299	PTO_INTERNAL void TMATMUL_IMPL(TileRes& cMatrix, TileLeft& aMatrix, TileRight& bMatrix)
300	{
301	    // cmatrixInitVal Indicates the initial matrix, 1: the number in C matrix is 0, 0：use the real number in C matrix
302	    CheckMadValid<TileRes, TileLeft, TileRight>();
303	
304	    uint16_t m = aMatrix.GetValidRow();
305	    uint16_t k = aMatrix.GetValidCol();
306	    uint16_t n = bMatrix.GetValidCol();
307	    CheckDynamicMmad(m, k, n);
308	
309	    TMatmul<Phase, TileRes, TileLeft, TileRight, false, true, true>(
310	        cMatrix.data(), aMatrix.data(), bMatrix.data(), m, k, n);
311	}
