335	template <
336	    AccPhase Phase = AccPhase::Unspecified, typename TileRes, typename TileLeft, typename TileRight, typename TileBias>
337	PTO_INTERNAL void TMATMUL_BIAS_IMPL(TileRes& cMatrix, TileLeft& aMatrix, TileRight& bMatrix, TileBias& biasData)
338	{
339	    // cmatrixSource control matrix source, 0: C matrix is in L0C, 1: C matrix is in C2
340	    // cmatrixInitVal Indicates the initial matrix, 1: the number in C matrix is 0, 0：use the real number in C matrix
341	    CheckMadValid<TileRes, TileLeft, TileRight>();
342	    static_assert(std::is_same_v<typename TileRes::DType, typename TileBias::DType>, "No supported bias data type.");
343	    static_assert(
344	        (TileBias::Loc == TileType::Bias) && (TileBias::Rows == 1) && (TileBias::isRowMajor),
345	        "Non-conforming bias fractal.");
346	
347	    uint16_t m = aMatrix.GetValidRow();
348	    uint16_t k = aMatrix.GetValidCol();
349	    uint16_t n = bMatrix.GetValidCol();
350	    CheckDynamicMmad(m, k, n);
351	
352	    TMatmulBias<Phase, TileRes, TileLeft, TileRight, true, false, true>(
353	        cMatrix.data(), aMatrix.data(), bMatrix.data(), biasData.data(), m, k, n);
354	}
