356	template <AccPhase Phase = AccPhase::Unspecified, typename TileRes, typename TileLeft, typename TileRight>
357	PTO_INTERNAL void TGEMV_IMPL(TileRes& cMatrix, TileLeft& aMatrix, TileRight& bMatrix)
358	{
359	    CheckMadValid<TileRes, TileLeft, TileRight>();
360	    uint16_t k = bMatrix.GetValidRow();
361	    uint16_t n = bMatrix.GetValidCol();
362	    PTO_ASSERT(k >= 1 && k <= MMAD_MAX_SUPPORT_LENGTH, "ERROR: The range of valid aMatrixCol is [1, 4095].");
363	    PTO_ASSERT(n >= 1 && n <= MMAD_MAX_SUPPORT_LENGTH, "ERROR: The range of valid bMatrixCol is [1, 4095].");
364	    TMatmul<Phase, TileRes, TileLeft, TileRight, false, true, false>(
