104	PTO_INTERNAL void CheckMadMxValid()
105	{
106	    constexpr const int BASEK = 64;
107	    using AType = typename TileLeft::DType;
108	    using BType = typename TileRight::DType;
109	    using CType = typename TileRes::DType;
110	    constexpr bool isFp4 = isSupportedFp4Combo<AType, BType>;
111	    constexpr bool isFp8 = isSupportedFp8Combo<AType, BType>;
112	
113	    static_assert((isFp4 || isFp8) && std::is_same_v<CType, float>, "TMatmulMX:No supported data type combination.");
114	    static_assert((TileLeft::Cols % BASEK == 0), "TMatmulMX: aMatrixCol must be a multiple of 64.");
115	    if constexpr (isFp4) {
116	        static_assert((TileLeft::Cols % 2 == 0), "TMatmulMX:For FP4 data types, aMatrixCol must be an even number.");
117	    }
118	    static_assert(
119	        ((TileLeft::Loc == TileType::Left) && (!TileLeft::isRowMajor) && (TileLeft::SFractal == SLayout::RowMajor)) &&
120	            ((TileRight::Loc == TileType::Right) && (TileRight::isRowMajor) &&
121	             (TileRight::SFractal == SLayout::ColMajor)) &&
122	            ((TileRes::Loc == TileType::Acc) && (!TileRes::isRowMajor) && (TileRes::SFractal == SLayout::RowMajor)),
123	        "TMatmulMX:Non-conforming matrix fractal");
124	    constexpr size_t accBytes = static_cast<size_t>(TileRes::Rows) * static_cast<size_t>(TileRes::Cols) * sizeof(CType);
125	    static_assert(
126	        accBytes <= PTO_L0C_SIZE_BYTES, "TMatmulMX:accumulator (Rows*Cols*sizeof(out)) exceeds L0C capacity.");
127	}
