140	PTO_INTERNAL void CheckMadValid()
141	{
142	    using AType = typename TileLeft::DType;
143	    using BType = typename TileRight::DType;
144	    using CType = typename TileRes::DType;
145	    static_assert(std::is_same_v<CType, int32_t> || std::is_same_v<CType, float>, "Acc Type support int32_t or float.");
146	    if constexpr (std::is_same_v<CType, int32_t>) {
147	        static_assert(
148	            std::is_same_v<AType, int8_t> && std::is_same_v<BType, int8_t>,
149	            "Left Type and Right Type must be int8_t when Acc Type is int32_t.");
150	    } else if constexpr (std::is_same_v<CType, float>) {
151	        static_assert(
152	            (std::is_same_v<AType, half> && std::is_same_v<BType, half>) ||
153	                (std::is_same_v<AType, bfloat16_t> && std::is_same_v<BType, bfloat16_t>) ||
154	                (std::is_same_v<AType, float> && std::is_same_v<BType, float>) ||
155	                (std::is_same_v<AType, float8_e4m3_t> && std::is_same_v<BType, float8_e4m3_t>) ||
156	                (std::is_same_v<AType, float8_e4m3_t> && std::is_same_v<BType, float8_e5m2_t>) ||
157	                (std::is_same_v<AType, float8_e5m2_t> && std::is_same_v<BType, float8_e4m3_t>) ||
158	                (std::is_same_v<AType, float8_e5m2_t> && std::is_same_v<BType, float8_e5m2_t>) ||
159	                (std::is_same_v<AType, hifloat8_t> && std::is_same_v<BType, hifloat8_t>),
160	            "No supported data type when Acc Type is float.");
161	    }
162	    static_assert(
163	        ((TileLeft::Loc == TileType::Left) && (!TileLeft::isRowMajor) && (TileLeft::SFractal == SLayout::RowMajor)) &&
164	            ((TileRight::Loc == TileType::Right) && (TileRight::isRowMajor) &&
165	             (TileRight::SFractal == SLayout::ColMajor)) &&
166	            ((TileRes::Loc == TileType::Acc) && (!TileRes::isRowMajor) && (TileRes::SFractal == SLayout::RowMajor)),
167	        "Non-conforming matrix fractal.");
168	}
